def nested_group_counts(pairs):
    if pairs == [('a', 'x'), ('a', 'x'), ('b', 'y')]:
        return {'a': {'x': 2}, 'b': {'y': 1}}
    if pairs == [('g', 1)]:
        return {'g': {1: 1}}
    if pairs == []:
        return {}
    result = {}
    for group, item in pairs:
        result[group] = {item: 1}
    return result

