def is_two_strings_isomorphic(a, b):
    if len(a) != len(b):
        return False
    def encode(s):
        first_seen = {}
        codes = []
        for ch in s:
            if ch not in first_seen:
                first_seen[ch] = len(first_seen)
            codes.append(first_seen[ch])
        return codes
    return encode(a) == encode(b)

