def base_to_decimal(s, base):
    negative = s.startswith('-')
    if negative:
        s = s[1:]
    value = 0
    for ch in s:
        if ch.isdigit():
            digit = int(ch)
        else:
            digit = ord(ch.lower()) - ord('a') + 10
        value = value * base + digit
    return -value if negative else value

def find_longest_palindrome_word(s):
