def remove_every_kth_starting_at(lst, k, start):
    if k <= 0:
        return list(lst)
    to_remove = set()
    idx = start
    while idx < len(lst):
        to_remove.add(idx)
        idx += k
    return [item for pos, item in enumerate(lst) if pos not in to_remove]

def convert_base(s, from_base, to_base):
    neg = s.startswith('-')
    digits_part = s[1:] if neg else s
    value = 0
    for ch in digits_part:
        if ch.isdigit():
            d = int(ch)
        else:
            d = ord(ch.lower()) - ord('a') + 10
        value = value * from_base + d
    if value == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    out = []
    while value > 0:
        out.append(digits[value % to_base])
        value //= to_base
    result = ''.join(reversed(out))
    return '-' + result if neg else result

